  (* [comment removed for export] *)
  Ltac x33dec ARR BB i r last :=
    zstep; zstep;
    lazymatch goal with |- context [Z_to_bv 64 (((bv_unsigned ?c ≪ ?b) mod 18446744073709551616) ≫ ?sh)] =>
      let v := fresh "v" in let EV := fresh "EV" in let VR := fresh "VR" in
      remember (((bv_unsigned c ≪ b) mod 18446744073709551616) ≫ sh) as v eqn:EV;
      assert (VR : 0 <= v < 2^tl) by (subst v; apply x4_idx_bound; [lia| apply bv_unsigned_in_range]);
      clear EV;
      zstep; zstep; rewrite Z.shiftl_mul_pow2 by lia; change (2^1) with 2; replace (v * 2) with (2 * v) by ring;
      let RC0 := fresh "RC" in let RC1 := fresh "RC" in
      lazymatch goal with CE : bytes_at psegs ?mm (DT + 4) cbs |- _ =>
        destruct (x1_cell_rd psegs mm (DT + 4) cells (Z.to_nat (2 * 2^tl)) v ltac:(rewrite <- ECB; exact CE)
                    ltac:(lia) ltac:(lia) ltac:(lia)) as [RC0 RC1] end;
      let NBc := fresh "NB" in let BYc := fresh "BY" in
      lazymatch goal with TCK : forall i, 0 <= i < 2^tl -> _ |- _ => destruct (TCK v VR) as (NBc & BYc) end;
      let c := fresh "c" in set (c := nth (Z.to_nat v) cells x1_default) in *;
      zstep; zstep; clear RC0 RC1; zstep;
      rewrite ?(byte_lit (x1_nbBits c)) by lia;
      lazymatch type of BB with 0 <= ?bo <= ?bm =>
        let w := getreg r in
        lazymatch w with Z_to_bv 64 ?E =>
          let b' := fresh "bits" in let EB := fresh "EB" in let BB' := fresh "BB'" in
          remember E as b' eqn:EB;
          assert (BB' : 0 <= b' <= bm + 12) by (subst b'; rewrite ?swrap32_eq by lia; Z.div_mod_to_equations; lia);
          clear EB BB; rename BB' into BB
        end
      end;
      (lazymatch last with true => zstep | false => idtac end);
      u8_sok ARR i; zstep; u8_store ARR i (x1_byte c); [rewrite byte_lit by lia; reflexivity|];
      clearbody c
    end.

  (* [comment removed for export] *)
  Notation HD pc mm q pt bits xc t2 a1 a3 t3 t4 t5 t6 :=
    (ST pc mm xc (Z_to_bv 64 (DST + Q3 - 3)) (Z_to_bv 64 (64 - tl)) t2 a1 a3 (Z_to_bv 64 67064) (Z_to_bv 64 (DST + q))
        (Z_to_bv 64 64) (Z_to_bv 64 bits) (Z_to_bv 64 (SS + O3 + pt)) t3 t4 t5 t6).

  (* [comment removed for export] *)
  Lemma x33_join : forall q pt nb bits flag mm (xc a1 a3 t4 t5 t6 : word),
    X4F' mm SPL BD -> 0 <= q <= Q3 -> 0 <= nb <= pt -> nb <= 8 -> pt - nb + 8 <= L3 -> 0 <= bits <= 64 ->
    (flag = 0 \/ flag = 1) ->
    (forall q' pt' bits' mm' (xc' t2' a1' a3' t3' t4' t5' t6' : word),
       X4F' mm' SPL BD -> q + 4 <= q' <= Q3 -> 0 <= pt' -> (pt' = 0 \/ pt' + 8 <= L3) -> 0 <= bits' <= 64 ->
       evt psegs POST (HD 0x1a2fc mm' q' pt' bits' xc' t2' a1' a3' t3' t4' t5' t6')) ->
    evt psegs POST (HD 0x1a340 mm q pt bits xc (Z_to_bv 64 flag) a1 a3 (Z_to_bv 64 nb) t4 t5 t6).
Proof using All.
